Looking at this problem:

- Map each character to a digit 0–9, all distinct, no leading zeros (first char of every word and of the result can't be 0), and the column-wise sum with carries must match the result.
- Key observations: if any word is longer than `result`, it's impossible (a word of length L is ≥ 10^(L-1), while result of length R is < 10^R, so L ≤ R is required).
- I do backtracking **column by column** from the least significant digit, maintaining a carry. For each column, I branch over assignments for the column's unassigned word letters; the result letter of that column is then *forced* to `(carry + sum of word digits) % 10` (or just compared if already assigned), which gives strong pruning (~1/10 survival per column). With ≤ 10 letters, ≤ 5 words, ≤ 7 columns, the search tree stays tiny (worst case ~a few million cheap operations).

I verified the logic against all three examples (e.g. SEND+MORE=MONEY: column carries force Y=2, N via 6+8+1=15, O=0, M=1, final carry 0 → true; LEET+CODE=POINT exhausts → false).

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution {
    int R_ = 0;
    vector<vector<int>> colSum_;   // per column: word letter ids (one entry per word occurrence)
    vector<vector<int>> colDist_;  // per column: distinct word letter ids
    vector<int> colRes_;           // per column: result letter id
    vector<vector<int>> needBuf_;  // per column scratch: still unassigned letters
    vector<int> assign_;           // letter id -> digit (-1 = unassigned)
    vector<char> lead_;            // letter id -> cannot be zero
    bool used_[10];

    bool dfsCol(int col, int carry) {
        if (col == R_) return carry == 0;
        vector<int>& need = needBuf_[col];
        need.clear();
        for (int id : colDist_[col])
            if (assign_[id] < 0) need.push_back(id);
        return place(col, carry, need, 0);
    }

    bool place(int col, int carry, vector<int>& need, int k) {
        if (k == (int)need.size()) {
            int total = carry;
            for (int id : colSum_[col]) total += assign_[id];
            int d = total % 10;
            int rid = colRes_[col];
            if (assign_[rid] >= 0)
                return assign_[rid] == d && dfsCol(col + 1, total / 10);
            if (used_[d] || (d == 0 && lead_[rid])) return false;
            assign_[rid] = d;
            used_[d] = true;
            if (dfsCol(col + 1, total / 10)) return true;
            assign_[rid] = -1;
            used_[d] = false;
            return false;
        }
        int id = need[k];
        for (int d = 0; d < 10; ++d) {
            if (used_[d] || (d == 0 && lead_[id])) continue;
            assign_[id] = d;
            used_[d] = true;
            if (place(col, carry, need, k + 1)) return true;
            assign_[id] = -1;
            used_[d] = false;
        }
        return false;
    }

public:
    bool isSolvable(vector<string>& words, string result) {
        const int R = (int)result.size();
        for (const string& w : words)
            if ((int)w.size() > R) return false;

        vector<string> rw;
        rw.reserve(words.size());
        for (const string& w : words) rw.emplace_back(w.rbegin(), w.rend());
        const string rr(result.rbegin(), result.rend());

        int idOf[26];
        memset(idOf, -1, sizeof(idOf));
        int n = 0;
        auto getId = [&](char c) -> int {
            int& x = idOf[c - 'A'];
            if (x < 0) x = n++;
            return x;
        };

        vector<vector<int>> colSum(R), colDist(R);
        vector<int> colRes(R);
        for (int i = 0; i < R; ++i) {
            for (const string& w : rw)
                if ((int)w.size() > i) colSum[i].push_back(getId(w[i]));
            colRes[i] = getId(rr[i]);
            vector<int> v = colSum[i];
            sort(v.begin(), v.end());
            v.erase(unique(v.begin(), v.end()), v.end());
            colDist[i] = move(v);
        }

        vector<char> lead(n, 0);
        for (const string& w : words) lead[getId(w[0])] = 1;
        lead[getId(result[0])] = 1;

        if (n > 10) return false;

        R_ = R;
        colSum_ = move(colSum);
        colDist_ = move(colDist);
        colRes_ = move(colRes);
        lead_ = move(lead);
        needBuf_.assign(R, vector<int>());
        assign_.assign(n, -1);
        memset(used_, 0, sizeof(used_));

        return dfsCol(0, 0);
    }
};
```

