```cpp
class Solution {
    int R;
    vector<vector<int>> colSum;    // per column: letter ids with multiplicity (from words)
    vector<vector<int>> colBranch; // per column: distinct letter ids from words
    vector<int> colRes;            // per column: result letter id
    vector<int> assign;            // letter id -> digit or -1
    bool used[10];
    vector<bool> leading;          // letter id -> cannot be 0

    bool solve(int col, int carry) {
        if (col == R) return carry == 0;
        // gather unassigned word letters
        vector<int> need;
        for (int id : colBranch[col]) if (assign[id] < 0) need.push_back(id);
        return fill(col, carry, need, 0);
    }

    bool fill(int col, int carry, vector<int>& need, size_t k) {
        if (k == need.size()) {
            int total = carry;
            for (int id : colSum[col]) total += assign[id];
            int resId = colRes[col];
            int d = total % 10;
            if (assign[resId] >= 0) {
                if (assign[resId] != d) return false;
                return next(col, total / 10);
            }
            // result letter unassigned (and distinct from word letters here)
            if (used[d]) return false;
            if (d == 0 && leading[resId]) return false;
            assign[resId] = d; used[d] = true;
            if (next(col, total / 10)) return true;
            assign[resId] = -1; used[d] = false;
            return false;
        }
        int id = need[k];
        for (int d = 0; d < 10; d++) {
            if (used[d]) continue;
            if (d == 0 && leading[id]) continue;
            assign[id] = d; used[d] = true;
            if (fill(col, carry, need, k + 1)) return true;
            assign[id] = -1; used[d] = false;
        }
        return false;
    }

    bool next(int col, int carry) {
        if (col + 1 == R) return carry == 0;
        return solve(col + 1, carry);
    }

public:
    bool isSolvable(vector<string>& words, string result) {
        int R = result.size();
        for (auto& w : words) if ((int)w.size() > R) return false;

        vector<string> rw;
        for (auto& w : words) rw.emplace_back(w.rbegin(), w.rend());
        string rr(result.rbegin(), result.rend());

        int id[26]; fill(begin(id), end(id), -1);
        int n = 0;
        auto getId = [&](char c) {
            int& x = id[c - 'A'];
            if (x < 0) x = n++;
            return x;
        };

        vector<vector<int>> colSum(R), colBranch(R);
        vector<int> colRes(R);
        for (int i = 0; i < R; i++) {
            for (auto& w : rw) if ((int)w.size() > i) colSum[i].push_back(getId(w[i]));
            colRes[i] = getId(rr[i]);
            // distinct word letters
            vector<int> v = colSum[i];
            sort(v.begin(), v.end());
            v.erase(unique(v.begin(), v.end()), v.end());
            colBranch[i] = move(v);
        }

        vector<bool> leading(n, false);
        for (auto& w : words) leading[getId(w[0])] = true;
        leading[getId(result[0])] = true;

        this->R = R;
        this->colSum = move(colSum);
        this->colBranch = move(colBranch);
        this->colRes = move(colRes);
        this->leading = move(leading);
        assign.assign(n, -1);
        memset(used, 0, sizeof(used));

        return solve(0, 0);
    }
};
