```cpp
class Solution {
    int R_;
    vector<vector<int>> colSum_;    // letter ids per column (words, with multiplicity)
    vector<vector<int>> colDist_;   // distinct word-letter ids per column
    vector<int> colRes_;            // result letter id per column
    vector<int> assign_;            // per letter: digit or -1
    vector<bool> lead_;
    bool used_[10];

    bool solve(int col, int carry) {
        if (col == R_) return carry == 0;
        vector<int> need;
        for (int id : colDist_[col])
            if (assign_[id] < 0) need.push_back(id);
        return fill(col, carry, need, 0);
    }

    bool fill(int col, int carry, vector<int>& need, int k) {
        if (k == (int)need.size()) {
            int total = carry;
            for (int id : colSum_[col]) total += assign_[id];
            int d = total % 10;
            int rid = colRes_[col];
            if (assign_[rid] >= 0) {
                return assign_[rid] == d && solve(col + 1, total / 10);
            }
            if (used_[d]) return false;
            if (d == 0 && lead_[rid]) return false;
            assign_[rid] = d; used_[d] = true;
            if (solve(col + 1, total / 10)) return true;
            assign_[rid] = -1; used_[d] = false;
            return false;
        }
        int id = need[k];
        for (int d = 0; d < 10; ++d) {
            if (used_[d]) continue;
            if (d == 0 && lead_[id]) continue;
            assign_[id] = d; used_[d] = true;
            if (fill(col, carry, need, k + 1)) return true;
            assign_[id] = -1; used_[d] = false;
        }
        return false;
    }

public:
    bool isSolvable(vector<string>& words, string result) {
        const int R = result.size();
        for (const auto& w : words)
            if ((int)w.size() > R) return false;

        // reversed strings
        vector<string> rw;
        rw.reserve(words.size());
        for (const auto& w : words) rw.emplace_back(w.rbegin(), w.rend());
        const string rr(result.rbegin(), result.rend());

        int idOf[26];
        for (int i = 0; i < 26; ++i) idOf[i] = -1;
        int n = 0;
        auto getId = [&](char c) {
            int& x = idOf[c - 'A'];
            if (x < 0) x = n++;
            return x;
        };

        vector<vector<int>> colSum(R), colDist(R);
        vector<int> colRes(R);
        for (int i = 0; i < R; ++i) {
            for (const auto& w : rw)
                if ((int)w.size() > i) colSum[i].push_back(getId(w[i]));
            colRes[i] = getId(rr[i]);
            vector<int> v = colSum[i];
            sort(v.begin(), v.end());
            v.erase(unique(v.begin(), v.end()), v.end());
            colDist[i] = move(v);
        }

        vector<bool> lead(n, false);
        for (const auto& w : words) lead[getId(w[0])] = true;
        lead[getId(result[0])] = true;

        R_ = R;
        colSum_ = move(colSum);
        colDist_ = move(colDist);
        colRes_ = move(colRes);
        lead_ = move(lead);
        assign_.assign(n, -1);
        for (int i = 0; i < 10; ++i) used_[i] = false;

        return solve(0, 0);
    }
};
