#include <bits/stdc++.h>
using namespace std;

class Solution {
    int R_ = 0;
    vector<vector<int>> colSum_;   // word letter ids per column (with multiplicity)
    vector<vector<int>> colDist_;  // distinct word letter ids per column
    vector<int> colRes_;           // result letter id per column
    vector<vector<int>> needBuf_;  // per-column scratch for unassigned letters
    vector<int> assign_;           // letter id -> digit (-1 = unassigned)
    vector<char> lead_;            // letter id -> cannot be zero
    bool used_[10];

    bool dfsCol(int col, int carry) {
        if (col == R_) return carry == 0;
        vector<int>& need = needBuf_[col];
        need.clear();
        for (int id : colDist_[col])
            if (assign_[id] < 0) need.push_back(id);
        return place(col, carry, need, 0);
    }

    bool place(int col, int carry, vector<int>& need, int k) {
        if (k == (int)need.size()) {
            int total = carry;
            for (int id : colSum_[col]) total += assign_[id];
            int d = total % 10;
            int rid = colRes_[col];
            if (assign_[rid] >= 0)
                return assign_[rid] == d && dfsCol(col + 1, total / 10);
            if (used_[d] || (d == 0 && lead_[rid])) return false;
            assign_[rid] = d;
            used_[d] = true;
            if (dfsCol(col + 1, total / 10)) return true;
            assign_[rid] = -1;
            used_[d] = false;
            return false;
        }
        int id = need[k];
        for (int d = 0; d < 10; ++d) {
            if (used_[d] || (d == 0 && lead_[id])) continue;
            assign_[id] = d;
            used_[d] = true;
            if (place(col, carry, need, k + 1)) return true;
            assign_[id] = -1;
