class Solution {
public:
    int numFactoredBinaryTrees(vector<int>& arr) {
        const int MOD = 1'000'000'007;
        sort(arr.begin(), arr.end());
        int n = arr.size();
        unordered_map<long long, long long> dp;
        dp.reserve(n * 2);
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            long long count = 1;
            for (int j = 0; j < i; ++j) {
                if (arr[i] % arr[j] == 0) {
                    long long factor = (long long)arr[i] / arr[j];
                    auto it = dp.find(factor);
                    if (it != dp.end()) {
                        count = (count + dp[arr[j]] * it->second) % MOD;
                    }
                }
            }
            dp[arr[i]] = count;
            ans = (ans + count) % MOD;
        }
        return (int)ans;
    }
};
```

