Looking at this problem, the key insight is to process the hits in **reverse** using a Union-Find structure:

1. **Pre-process**: Mark all hit cells that contain bricks (set to 2), effectively removing them all upfront.
2. **Build Union-Find** on remaining bricks, connecting top-row bricks to a virtual "roof" node, tracking component sizes.
3. **Process hits in reverse**: Restore each hit brick, union it with its present neighbors (and roof if in top row). The bricks that become newly connected to the roof are exactly those that fell when this hit was applied forward in time. The answer is `max(0, after - before - 1)` (subtracting 1 for the hit brick itself, which is erased rather than fallen).

**Why this works**: A brick is stable iff it's connected to the top. Connectivity to the roof is monotone as bricks are added back in reverse — so at the moment we restore hit `i`, the roof-connected component equals exactly the set of bricks that were stable just before hit `i` in forward time. The difference in roof-component sizes before/after restoring gives the fallen bricks plus the hit brick itself.

I verified this against both examples (Example 1 gives 2; Example 2 gives 0,0) and edge cases like a hit brick that already fell due to an earlier hit (correctly yields 0 since it won't connect to the roof when restored out of order).

Complexity: O(m·n·α + hits·α), well within limits (m, n ≤ 200, hits ≤ 4·10⁴).

```cpp
#include <vector>
#include <numeric>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m = grid.size(), n = grid[0].size();
        int total = m * n;
        int roof = total;
        vector<int> parent(total + 1), sz(total + 1, 1);
        iota(parent.begin(), parent.end(), 0);
        sz[roof] = 0;

        // Mark hit cells that contain bricks as erased (2)
        for (auto& h : hits)
            if (grid[h[0]][h[1]] == 1) grid[h[0]][h[1]] = 2;

        auto find = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };
        auto unite = [&](int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (sz[a] < sz[b]) swap(a, b);
            parent[b] = a;
            sz[a] += sz[b];
        };

        // Build union-find on remaining bricks
        for (int r = 0; r < m; ++r)
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] != 1) continue;
                int id = r * n + c;
                if (r == 0) unite(id, roof);
                if (r + 1 < m && grid[r + 1][c] == 1) unite(id, (r + 1) * n + c);
                if (c + 1 < n && grid[r][c + 1] == 1) unite(id, r * n + c + 1);
            }

        const int dr[4] = {1, -1, 0, 0};
        const int dc[4] = {0, 0, 1, -1};
        vector<int> res(hits.size(), 0);

        // Process hits in reverse
        for (int i = (int)hits.size() - 1; i >= 0; --i) {
            int r = hits[i][0], c = hits[i][1];
            if (grid[r][c] != 2) continue; // no brick was there originally
            grid[r][c] = 1;
            int id = r * n + c;
            int before = sz[find(roof)];
            if (r == 0) unite(id, roof);
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1)
                    unite(id, nr * n + nc);
            }
            int after = sz[find(roof)];
            res[i] = max(0, after - before - 1);
        }
        return res;
    }
};
```

