```cpp
class Solution {
public:
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m = grid.size(), n = grid[0].size();
        int total = m * n;
        int roof = total;
        vector<int> parent(total + 1), sz(total + 1, 1);
        iota(parent.begin(), parent.end(), 0);
        sz[roof] = 0;

        // Mark hit cells that have bricks
        for (auto& h : hits) {
            if (grid[h[0]][h[1]] == 1) grid[h[0]][h[1]] = 2;
        }

        auto find = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };

        auto unite = [&](int a, int b) {
            a = find(a); b = find(b);
            if (a == b) return;
            if (sz[a] < sz[b]) swap(a, b);
            parent[b] = a;
            sz[a] += sz[b];
        };

        int dr[4] = {1, -1, 0, 0};
        int dc[4] = {0, 0, 1, -1};

        // Build initial components
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] != 1) continue;
                int id = r * n + c;
                if (r == 0) unite(id, roof);
                if (r + 1 < m && grid[r + 1][c] == 1) unite(id, (r + 1) * n + c);
                if (c + 1 < n && grid[r][c + 1] == 1) unite(id, r * n + c + 1);
            }
        }

        vector<int> res(hits.size(), 0);
        for (int i = (int)hits.size() - 1; i >= 0; --i) {
            int r = hits[i][0], c = hits[i][1];
            if (grid[r][c] != 2) continue; // no brick was hit
            grid[r][c] = 1;
            int id = r * n + c;
            int before = sz[find(roof)];
            if (r == 0) unite(id, roof);
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1)
                    unite(id, nr * n + nc);
            }
            int after = sz[find(roof)];
            res[i] = max(0, after - before - 1);
        }

        // Restore grid (optional)
        // All 2s have been restored to 1 in the loop; cells that were 0 remain 0.
        // Actually cells marked 2 are all restored. Grid is back to original.

        return res;
    }
