class CustomStack {
    vector<int> st;
    vector<int> add;
    int top; // number of elements, also index of next free slot
public:
    CustomStack(int maxSize) {
        st.assign(maxSize, 0);
        add.assign(maxSize, 0);
        top = 0;
    }

    void push(int x) {
        if (top < (int)st.size()) {
            st[top] = x;
            add[top] = 0; // new element has no pending increment
            top++;
        }
    }

    int pop() {
        if (top == 0) return -1;
        top--;
        int res = st[top] + add[top];
        if (top > 0) add[top-1] += add[top];
        add[top] = 0;
        return res;
    }

    void increment(int k, int val) {
        int limit = min(k, top);
        if (limit > 0) add[limit-1] += val;
    }
};
