```cpp
class MKAverage {
    int m, k;
    queue<int> q;
    multiset<int> lo, mid, hi;
    long long sumLo = 0, sumMid = 0, sumHi = 0;

    void loToMid() {
        auto it = prev(lo.end());
        int v = *it;
        sumLo -= v; sumMid += v;
        lo.erase(it);
        mid.insert(v);
    }
    void midToLo() {
        auto it = mid.begin();
        int v = *it;
        sumMid -= v; sumLo += v;
        mid.erase(it);
        lo.insert(v);
    }
    void midToHi() {
        auto it = prev(mid.end());
        int v = *it;
        sumMid -= v; sumHi += v;
        mid.erase(it);
        hi.insert(v);
    }
    void hiToMid() {
        auto it = hi.begin();
        int v = *it;
        sumHi -= v; sumMid += v;
        hi.erase(it);
        mid.insert(v);
    }
    void rebalance() {
        while ((int)lo.size() > k) loToMid();
        while ((int)hi.size() > k) hiToMid();
        while ((int)lo.size() < k && !mid.empty()) midToLo();
        while ((int)hi.size() < k && !mid.empty()) midToHi();
    }

public:
    MKAverage(int m, int k) : m(m), k(k) {}

    void addElement(int num) {
        q.push(num);
        if (!lo.empty() && num <= *lo.rbegin()) {
            lo.insert(num); sumLo += num;
        } else if (!mid.empty() && num <= *mid.rbegin()) {
            mid.insert(num); sumMid += num;
        } else {
            hi.insert(num); sumHi += num;
        }
        rebalance();
        if ((int)q.size() > m) {
            int v = q.front(); q.pop();
            auto it = lo.find(v);
            if (it != lo.end()) { sumLo -= v; lo.erase(it); }
            else if ((it = mid.find(v)) != mid.end()) { sumMid -= v; mid.erase(it); }
            else { it = hi.find(v); sumHi -= v; hi.erase(it); }
            rebalance();
        }
    }

    int calculateMKAverage() {
        if ((int)q.size() < m) return -1;
        return (int)(sumMid / (m - 2 * k));
    }
};
