```cpp
class Solution {
public:
    int largestMagicSquare(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();

        // rowPrefix[i][j] = sum of grid[i][0..j-1]
        vector<vector<long long>> rowPrefix(m, vector<long long>(n + 1, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                rowPrefix[i][j + 1] = rowPrefix[i][j] + grid[i][j];

        // colPrefix[i][j] = sum of grid[0..i-1][j]
        vector<vector<long long>> colPrefix(m + 1, vector<long long>(n, 0));
        for (int j = 0; j < n; j++)
            for (int i = 0; i < m; i++)
                colPrefix[i + 1][j] = colPrefix[i][j] + grid[i][j];

        // diagPrefix[i+1][j+1] = sum of main diagonal ending at (i,j)
        vector<vector<long long>> diagPrefix(m + 1, vector<long long>(n + 1, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                diagPrefix[i + 1][j + 1] = grid[i][j] + diagPrefix[i][j];

        // antiPrefix[i+1][j] = sum of anti-diagonal ending at (i,j) from top-right
        vector<vector<long long>> antiPrefix(m + 1, vector<long long>(n + 2, 0));
        for (int i = 0; i < m; i++)
            for (int j = n - 1; j >= 0; j--)
                antiPrefix[i + 1][j] = grid[i][j] + antiPrefix[i][j + 1];

        for (int k = min(m, n); k >= 2; k--) {
            for (int r = 0; r + k <= m; r++) {
                for (int c = 0; c + k <= n; c++) {
                    long long target = rowPrefix[r][c + k] - rowPrefix[r][c];
                    bool ok = true;
                    for (int i = 1; i < k && ok; i++)
                        if (rowPrefix[r + i][c + k] - rowPrefix[r + i][c] != target) ok = false;
                    for (int j = 0; j < k && ok; j++)
                        if (colPrefix[r + k][c + j] - colPrefix[r][c + j] != target) ok = false;
                    if (ok && diagPrefix[r + k][c + k] - diagPrefix[r][c] != target) ok = false;
                    if (ok && antiPrefix[r + k][c] - antiPrefix[r][c + k] != target) ok = false;
                    if (ok) return k;
                }
            }
        }
        return 1;
    }
};
```

