```cpp
class Solution {
public:
    int numComponents(ListNode* head, vector<int>& nums) {
        unordered_set<int> s(nums.begin(), nums.end());
        int count = 0;
        bool prevInSet = false;
        ListNode* cur = head;
        while (cur != nullptr) {
            bool inSet = s.count(cur->val) > 0;
            if (inSet && !prevInSet) {
                count++;
            }
            prevInSet = inSet;
            cur = cur->next;
        }
        return count;
    }
};
```

