Looking at this problem:

**Key insight:** Any optimal path turns around at most once. The harvested fruits always lie in some interval `[l, r]` containing `startPos`, and the minimum steps to cover that interval is:
- If both `l, r >= startPos`: `r - startPos` (just walk right)
- If both `l, r <= startPos`: `startPos - l` (just walk left)
- Otherwise: `(r - l) + min(startPos - l, r - startPos)` (go to nearer end first, then sweep to the far end)

**Approach:** Since fruits are sorted, use prefix sums + two pointers. For each left index `i`, find the maximal right index `j` such that the cost of covering `[fruits[i][0], fruits[j][0]]` is `<= k`. The cost is non-increasing as `l` increases (for fixed `r`), so `j` never moves backward — giving O(n) total.

**Verification with examples:**
- Example 1: window `[6,8]` from start 5 costs `8-5=3 ≤ 4`, sum = 9 ✓
- Example 2: window `[4,7]` costs `(7-4) + min(1,2) = 4 ≤ 4`, sum = 14 ✓  
- Example 3: no reachable fruit, answer 0 ✓

```cpp
class Solution {
public:
    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size();
        vector<long long> prefix(n + 1, 0);
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + fruits[i][1];

        long long ans = 0;
        int j = 0;
        for (int i = 0; i < n; i++) {
            if (j < i) j = i;
            long long l = fruits[i][0];
            while (j < n) {
                long long r = fruits[j][0];
                long long c;
                if (l >= startPos) {
                    c = r - startPos;
                } else if (r <= startPos) {
                    c = startPos - l;
                } else {
                    long long back = min((long long)startPos - l, r - startPos);
                    c = (r - l) + back;
                }
                if (c <= k) j++;
                else break;
            }
            if (j > i) ans = max(ans, prefix[j] - prefix[i]);
        }
        return (int)ans;
    }
};
```

