class Solution {
public:
    long long maxRunTime(int n, vector<int>& batteries) {
        long long total = 0;
        for (int b : batteries) total += b;
        long long lo = 1, hi = total / n, ans = 0;
        while (lo <= hi) {
            long long mid = lo + (hi - lo) / 2;
            long long avail = 0;
            for (int b : batteries) avail += min((long long)b, mid);
            if (avail >= (long long)n * mid) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
};
```

