class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        int n = flowers.size();
        sort(flowers.begin(), flowers.end());
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + flowers[i];

        int c0 = n - (int)(lower_bound(flowers.begin(), flowers.end(), target) - flowers.begin());

        long long ans = 0;
        long long cost = 0;
        for (int k = 0; k <= n; ++k) {
            if (k > 0) cost += max(0, target - flowers[n - k]);
            if (cost > newFlowers) break;
            if (k < c0) continue;
            long long rem = newFlowers - cost;
            int m = n - k;
            long long beauty;
            if (m == 0) {
                beauty = (long long)n * full;
            } else {
                int lo = 0, hi = target - 1;
                while (lo < hi) {
                    int mid = lo + (hi - lo + 1) / 2;
                    int cnt = (int)(lower_bound(flowers.begin(), flowers.begin() + m, mid) - flowers.begin());
                    long long c = (long long)mid * cnt - pre[cnt];
                    if (c <= rem) lo = mid;
                    else hi = mid - 1;
                }
                beauty = (long long)k * full + (long long)lo * partial;
            }
            ans = max(ans, beauty);
        }
        return ans;
    }
};
```

