class Solution {
public:
    int m, n;
    int dx[4] = {1,-1,0,0};
    int dy[4] = {0,0,1,-1};

    int countIslands(vector<vector<int>>& g) {
        vector<vector<bool>> vis(m, vector<bool>(n, false));
        int cnt = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (g[i][j] == 1 && !vis[i][j]) {
                    cnt++;
                    // BFS/DFS
                    stack<pair<int,int>> st;
                    st.push({i,j});
                    vis[i][j] = true;
                    while (!st.empty()) {
                        auto [x, y] = st.top(); st.pop();
                        for (int d = 0; d < 4; d++) {
                            int nx = x + dx[d], ny = y + dy[d];
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n && g[nx][ny] == 1 && !vis[nx][ny]) {
                                vis[nx][ny] = true;
                                st.push({nx, ny});
                            }
                        }
                    }
                }
            }
        }
        return cnt;
    }

    bool isDisconnected(vector<vector<int>>& g) {
        return countIslands(g) != 1;
    }

    int minDays(vector<vector<int>>& grid) {
        m = grid.size(); n = grid[0].size();
        if (isDisconnected(grid)) return 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                    if (isDisconnected(grid)) { grid[i][j] = 1; return 1; }
                    grid[i][j] = 1;
                }
            }
        }
        return 2;
    }
};
```

