Let me write it:

```cpp
class Solution {
public:
    int maxSizeSlices(vector<int>& slices) {
        int m = slices.size();
        int n = m / 3;
        auto solve = [&](vector<int>& b, int k) -> int {
            int L = b.size();
            // dp[j][i]: max sum picking j non-adjacent from first i elements
            // Use 2D array of (k+1) x (L+1), init to -inf, but handle j=0 as 0.
            const int NEG = -1e9;
            vector<vector<int>> dp(k + 1, vector<int>(L + 1, NEG));
            for (int i = 0; i <= L; i++) dp[0][i] = 0;
            for (int j = 1; j <= k; j++) {
                for (int i = 1; i <= L; i++) {
                    dp[j][i] = dp[j][i-1]; // don't take element i-1
                    if (i >= 2) {
                        if (dp[j-1][i-2] != NEG)
                            dp[j][i] = max(dp[j][i], dp[j-1][i-2] + b[i-1]);
                    } else {
                        // i == 1: take element 0 alone
                        if (j == 1) dp[j][i] = max(dp[j][i], b[0]);
                    }
                }
            }
            return dp[k][L];
        };
        vector<int> a(slices.begin(), slices.end() - 1); // slices[0..m-2]
        vector<int> b(slices.begin() + 1, slices.end()); // slices[1..m-1]
        return max(solve(a, n), solve(b, n));
    }
};
```

