Let me simplify with a cleaner formulation. Common approach:

```cpp
int solve(vector<int>& b, int k) {
    int L = b.size();
    // dp[i][j]: max sum picking j non-adjacent from first i
    vector<vector<int>> dp(L + 1, vector<int>(k + 1, INT_MIN / 2));
    for (int i = 0; i <= L; i++) dp[i][0] = 0;
    for (int i = 1; i <= L; i++) {
        for (int j = 1; j <= k; j++) {
            dp[i][j] = dp[i-1][j];
            long long take = (long long)(i >= 2 ? dp[i-2][j-1] : (j == 1 ? 0 : INT_MIN/2)) + b[i-1];
            if (take > dp[i][j]) dp[i][j] = (int)take;
        }
    }
    return dp[L][k];
}
```

