This is a classic Union-Find problem with restrictions checking.

Approach:
- Use DSU (Disjoint Set Union).
- For each request (u, v), find roots ru, rv. If already same, it's successful (true).
- Otherwise, tentatively merge: check all restrictions (x, y). If root(x) and root(y) would be in the same component after merging (i.e., {root(x), root(y)} == {ru, rv}), then the merge is not allowed — return false for this request.
- If no restriction is violated, perform the union and return true.

Complexity: O(requests * restrictions * α(n)) which is at most 1000*1000 = 10^6, fine.

Let me write the code:

```cpp
class Solution {
public:
    vector<int> parent;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    vector<bool> friendRequests(int n, vector<vector<int>>& restrictions, vector<vector<int>>& requests) {
        parent.resize(n);
        iota(parent.begin(), parent.end(), 0);

        vector<bool> result;
        result.reserve(requests.size());

        for (auto& req : requests) {
            int ru = find(req[0]), rv = find(req[1]);
            if (ru == rv) {
                result.push_back(true);
                continue;
            }
            bool ok = true;
            for (auto& r : restrictions) {
                int rx = find(r[0]), ry = find(r[1]);
                if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                parent[ru] = rv;
                result.push_back(true);
            } else {
                result.push_back(false);
            }
        }
        return result;
    }
};
```

