        }

        int month = monthMap[monthStr];

        // Format
        string result = yearStr + "-";
        if (month < 10) result += "0";
        result += to_string(month) + "-";
        if (day < 10) result += "0";
        result += to_string(day);

        return result;
    }
};
```

