class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        int l = 0, r = 0;
        for (char c : s) {
            if (c == '(') l++;
            else if (c == ')') {
                if (l > 0) l--;
                else r++;
            }
        }
        unordered_set<string> result;
        string current;
        dfs(s, 0, l, r, 0, current, result);
        return vector<string>(result.begin(), result.end());
    }

private:
    void dfs(const string& s, int idx, int l, int r, int open, string& current, unordered_set<string>& result) {
        if (l < 0 || r < 0 || open < 0) return;
        if (idx == s.size()) {
            if (l == 0 && r == 0 && open == 0) {
                result.insert(current);
            }
            return;
        }
        char c = s[idx];
        if (c == '(') {
            // keep
            current.push_back(c);
            dfs(s, idx + 1, l, r, open + 1, current, result);
            current.pop_back();
            // remove
            if (l > 0) {
                dfs(s, idx + 1, l - 1, r, open, current, result);
            }
        } else if (c == ')') {
            // keep
            current.push_back(c);
            dfs(s, idx + 1, l, r, open - 1, current, result);
            current.pop_back();
            // remove
            if (r > 0) {
                dfs(s, idx + 1, l, r - 1, open, current, result);
            }
        } else {
            current.push_back(c);
            dfs(s, idx + 1, l, r, open, current, result);
            current.pop_back();
        }
    }
};
```

