```cpp
class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        int l = 0, r = 0;
        for (char c : s) {
            if (c == '(') {
                ++l;
            } else if (c == ')') {
                if (l > 0) --l;
                else ++r;
            }
        }
        unordered_set<string> results;
        string current;
        current.reserve(s.size());
        dfs(s, 0, l, r, 0, current, results);
        return vector<string>(results.begin(), results.end());
    }

private:
    void dfs(const string& s, int idx, int l, int r, int open,
             string& current, unordered_set<string>& results) {
        if (idx == (int)s.size()) {
            if (l == 0 && r == 0 && open == 0) {
                results.insert(current);
            }
            return;
        }
        char c = s[idx];
        if (c == '(') {
            // Option 1: keep it.
            current.push_back(c);
            dfs(s, idx + 1, l, r, open + 1, current, results);
            current.pop_back();
            // Option 2: remove it.
            if (l > 0) {
                dfs(s, idx + 1, l - 1, r, open, current, results);
            }
        } else if (c == ')') {
            // Option 1: keep it (only useful if it doesn't break validity).
            current.push_back(c);
            dfs(s, idx + 1, l, r, open - 1, current, results);
            current.pop_back();
            // Option 2: remove it.
            if (r > 0) {
                dfs(s, idx + 1, l, r - 1, open, current, results);
            }
        } else {
            current.push_back(c);
            dfs(s, idx + 1, l, r, open, current, results);
            current.pop_back();
        }
    }
