```cpp
class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int n = target.size();
        int m = 1 << n;
        vector<int> dp(m, -1);
        dp[0] = 0;
        // convert stickers to counts
        vector<array<int,26>> cnt;
        for (auto& s : stickers) {
            array<int,26> c{}; 
            for (char ch : s) c[ch-'a']++;
            // check if sticker has any useful letter
            bool useful = false;
            for (int i = 0; i < n; i++) if (c[target[i]-'a'] > 0) { useful = true; break; }
            if (useful) cnt.push_back(c);
        }
        // BFS or DFS
        // DFS with memo
        function<int(int)> solve = [&](int mask) -> int {
            if (dp[mask] >= 0) return dp[mask];
            if (mask == 0) return 0;
            int res = INT_MAX;
            // find first unset bit
            int idx = 0;
            while (mask & (1<<idx)) idx++;
            char need = target[idx];
            for (auto& c : cnt) {
                if (c[need-'a'] == 0) continue;
                int newMask = mask;
                array<int,26> avail = c;
                for (int i = 0; i < n; i++) {
                    if (!(newMask & (1<<i))) {
                        int ch = target[i]-'a';
                        if (avail[ch] > 0) { avail[ch]--; newMask |= (1<<i); }
                    }
                }
                if (newMask != mask) {
                    int sub = solve(newMask);
                    if (sub != INT_MAX) res = min(res, sub + 1);
                }
            }
            dp[mask] = res;
            return res;
        };
        int full = m - 1;
        int ans = solve(full);
        return ans == INT_MAX ? -1 : ans;
    }
};
