        for (auto& s : stickers) {
            array<int,26> c{};
            for (char ch : s) c[ch - 'a']++;
            bool useful = false;
            for (int i = 0; i < n; i++)
                if (c[target[i] - 'a'] > 0) { useful = true; break; }
            if (useful) sts.push_back(c);
        }

        // dedupe
        sort(sts.begin(), sts.end());
        sts.erase(unique(sts.begin(), sts.end()), sts.end());

        // remove dominated
        vector<array<int,26>> keep;
        for (int i = 0; i < (int)sts.size(); i++) {
            bool dominated = false;
            for (int j = 0; j < (int)sts.size(); j++) {
                if (i == j) continue;
                bool ge = true;
                for (int c = 0; c < 26; c++)
                    if (sts[j][c] < sts[i][c]) { ge = false; break; }
                if (ge) { dominated = true; break; }
            }
            if (!dominated) keep.push_back(sts[i]);
        }

        function<int(int)> solve = [&](int mask) -> int {
            if (dp[mask] != -1) return dp[mask];
            int idx = 0;
            while (mask & (1 << idx)) idx++;
            int need = target[idx] - 'a';
            int res = INT_MAX;
            for (auto& c : keep) {
                if (c[need] == 0) continue;
                int nm = mask;
                array<int,26> avail = c;
                for (int i = 0; i < n; i++) {
                    if (!(nm & (1 << i))) {
                        int ch = target[i] - 'a';
