                            avail[ch]--;
                            nm |= 1 << i;
                        }
                    }
                }
                // nm != mask guaranteed since position idx covered
                int sub = solve(nm);
                if (sub != INT_MAX && sub + 1 < res) res = sub + 1;
            }
            dp[mask] = res;
            return res;
        };

        int ans = solve(full);
        return ans == INT_MAX ? -1 : ans;
    }
};
