Looking at this problem:

- n ≤ 28, so the tournament has at most ~5-6 rounds (28→14→7→4→2).
- firstPlayer (f) and secondPlayer (s) always win until they face each other; every other match's winner is our free choice.
- I do a DFS over the set of alive players (bitmask, ascending order = re-lining rule). For the current lineup, I check all front/end pairs: if f and s are paired, they meet this round (base case, cost 1). Otherwise, for each pair, if it involves f or s the winner is forced; otherwise branch on both outcomes. The middle player (odd count) auto-advances. Each transition adds 1 round; take min for earliest, max for latest.
- Memoize on the bitmask (the future depends only on the alive set; the popcount determines the round level, so no ambiguity). Reachable states are few (≤ ~150k), and branching per round is at most 2^12 at the first round for n=28, which is easily fast enough.

I verified against both examples: n=11, f=2, s=4 → [3,4]; n=5, f=1, s=5 → [1,1], plus several hand-checked cases like n=8, f=2, s=4 → [2,3].

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution {
    int n;
    int f, s;
    unordered_map<int, pair<int,int>> memo;

    pair<int,int> dfs(int mask) {
        auto it = memo.find(mask);
        if (it != memo.end()) return it->second;

        int ps[30];
        int m = 0;
        for (int i = 0; i < n; ++i)
            if ((mask >> i) & 1) ps[m++] = i + 1;

        // If the two best players are paired this round, they compete now.
        for (int i = 0, j = m - 1; i < j; ++i, --j) {
            int a = ps[i], b = ps[j];
            if ((a == f && b == s) || (a == s && b == f)) {
                memo[mask] = make_pair(1, 1);
                return memo[mask];
            }
        }

        int half = m / 2;
        int midBit = (m & 1) ? (1 << (ps[half] - 1)) : 0;

        // Enumerate all possible sets of winners for this round.
        vector<int> nexts;
        nexts.push_back(0);
        for (int i = 0; i < half; ++i) {
            int a = ps[i], b = ps[m - 1 - i];
            vector<int> nn;
            if (a == f || a == s) {
                int bit = 1 << (a - 1);
                for (int v : nexts) nn.push_back(v | bit);
            } else if (b == f || b == s) {
                int bit = 1 << (b - 1);
                for (int v : nexts) nn.push_back(v | bit);
            } else {
                int ba = 1 << (a - 1);
                int bb = 1 << (b - 1);
                for (int v : nexts) {
                    nn.push_back(v | ba);
                    nn.push_back(v | bb);
                }
            }
            nexts.swap(nn);
        }
        if (midBit != 0)
            for (int &v : nexts) v |= midBit;

        int mn = INT_MAX, mx = INT_MIN;
        for (int nm : nexts) {
            pair<int,int> r = dfs(nm);
            if (r.first + 1 < mn) mn = r.first + 1;
            if (r.second + 1 > mx) mx = r.second + 1;
        }
        memo[mask] = make_pair(mn, mx);
        return memo[mask];
    }

public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        this->n = n;
        f = firstPlayer;
        s = secondPlayer;
        memo.clear();
        pair<int,int> r = dfs((1 << n) - 1);
        return vector<int>{r.first, r.second};
    }
};
```

