```cpp
class Solution {
public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        int f = firstPlayer, s = secondPlayer;
        // memo[mask] = {earliest, latest} number of rounds from this state until f and s meet
        unordered_map<long long, pair<int,int>> memo;

        // We'll do DFS with explicit player list computation.
        // Use recursion with lambda.

        vector<int> players; // current players, filled per call

        // Use a recursive function taking mask.
        function<pair<int,int>(int)> dfs = [&](int mask) -> pair<int,int> {
            vector<int> ps;
            for (int i = 0; i < n; i++) if (mask >> i & 1) ps.push_back(i + 1);
            int m = ps.size();
            // check meeting
            for (int i = 0, j = m - 1; i < j; i++, j--) {
                int a = ps[i], b = ps[j];
                if ((a == f && b == s) || (a == s && b == f)) return {1, 1};
            }
            auto it = memo.find(mask);
            if (it != memo.end()) return it->second;

            int mn = INT_MAX, mx = INT_MIN;
            int midIdx = m / 2; // if m odd, ps[midIdx] is middle
            bool hasMid = (m % 2 == 1);

            // iterative/recursive enumeration over matches
            // matches: i from 0 to m/2 - 1 (when m even, i in [0, m/2-1]; when odd, same, middle excluded)

            // We'll do a small recursive lambda.
            function<void(int, int)> gen = [&](int i, int acc) {
                if (i == m / 2) {
                    int nm = acc;
                    if (hasMid) nm |= 1 << (ps[midIdx] - 1);
                    auto r = dfs(nm);
                    mn = min(mn, r.first + 1);
                    mx = max(mx, r.second + 1);
                    return;
                }
                int a = ps[i], b = ps[m - 1 - i];
                if (a == f || a == s) {
                    gen(i + 1, acc | (1 << (a - 1)));
                } else if (b == f || b == s) {
                    gen(i + 1, acc | (1 << (b - 1)));
                } else {
                    gen(i + 1, acc | (1 << (a - 1)));
                    gen(i + 1, acc | (1 << (b - 1)));
                }
            };
            gen(0, 0);
            memo[mask] = {mn, mx};
            return {mn, mx};
        };

        int start = (1 << n) - 1;
        auto r = dfs(start);
        return {r.first, r.second};
    }
};
```

