```cpp
class Solution {
    int n;
    int f, s;
    unordered_map<int, pair<int,int>> memo;

    pair<int,int> dfs(int mask) {
        auto it = memo.find(mask);
        if (it != memo.end()) return it->second;

        int ps[30];
        int m = 0;
        for (int i = 0; i < n; ++i)
            if ((mask >> i) & 1) ps[m++] = i + 1;

        // Check if f and s compete this round
        for (int i = 0, j = m - 1; i < j; ++i, --j) {
            int a = ps[i], b = ps[j];
            if ((a == f && b == s) || (a == s && b == f)) {
                memo[mask] = make_pair(1, 1);
                return memo[mask];
            }
        }

        int half = m / 2;
        int midBit = (m & 1) ? (1 << (ps[half] - 1)) : 0;

        // Enumerate all possible winner sets via BFS over matches
        vector<int> nexts;
        nexts.reserve(1 << half);
        nexts.push_back(0);
        for (int i = 0; i < half; ++i) {
            int a = ps[i], b = ps[m - 1 - i];
            vector<int> nn;
            if (a == f || a == s) {
                int bit = 1 << (a - 1);
                nn.reserve(nexts.size());
                for (int v : nexts) nn.push_back(v | bit);
            } else if (b == f || b == s) {
                int bit = 1 << (b - 1);
                nn.reserve(nexts.size());
                for (int v : nexts) nn.push_back(v | bit);
            } else {
                int ba = 1 << (a - 1), bb = 1 << (b - 1);
                nn.reserve(nexts.size() * 2);
                for (int v : nexts) { nn.push_back(v | ba); nn.push_back(v | bb); }
            }
            nexts.swap(nn);
        }
        if (midBit) for (int& v : nexts) v |= midBit;

        int mn = INT_MAX, mx = INT_MIN;
        for (int nm : nexts) {
            pair<int,int> r = dfs(nm);
            if (r.first + 1 < mn) mn = r.first + 1;
            if (r.second + 1 > mx) mx = r.second + 1;
        }
        memo[mask] = make_pair(mn, mx);
        return memo[mask];
    }

public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        this->n = n;
        f = firstPlayer;
        s = secondPlayer;
        memo.clear();
        pair<int,int> r = dfs((1 << n) - 1);
        return {r.first, r.second};
    }
