class Solution {
    int n;
    int f, s;
    unordered_map<int, pair<int,int>> memo;

    pair<int,int> dfs(int mask) {
        auto it = memo.find(mask);
        if (it != memo.end()) return it->second;

        int ps[30];
        int m = 0;
        for (int i = 0; i < n; ++i)
            if ((mask >> i) & 1) ps[m++] = i + 1;

        // If firstPlayer and secondPlayer are paired this round, meeting happens now.
        for (int i = 0, j = m - 1; i < j; ++i, --j) {
            int a = ps[i], b = ps[j];
            if ((a == f && b == s) || (a == s && b == f)) {
                return memo[mask] = {1, 1};
            }
        }

        int half = m / 2;
        int midBit = (m & 1) ? (1 << (ps[half] - 1)) : 0;

        vector<int> nexts{0};
        for (int i = 0; i < half; ++i) {
            int a = ps[i], b = ps[m - 1 - i];
