```cpp
class Solution {
public:
    vector<int> kWeakestRows(vector<vector<int>>& mat, int k) {
        int m = mat.size();
        vector<pair<int, int>> rows; // (soldier count, index)
        rows.reserve(m);
        for (int i = 0; i < m; i++) {
            int cnt = countSoldiers(mat[i]);
            rows.push_back({cnt, i});
        }
        sort(rows.begin(), rows.end());
        vector<int> result;
        result.reserve(k);
        for (int i = 0; i < k; i++) {
            result.push_back(rows[i].second);
        }
        return result;
    }

private:
    int countSoldiers(vector<int>& row) {
        int lo = 0, hi = row.size();
        // Find first index where row[idx] == 0
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (row[mid] == 1) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
};
```

