```cpp
class Solution {
public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        auto g = [](int a, int b) {
            while (b) { int t = a % b; a = b; b = t; }
            return a;
        };

        // Precompute coprime value lists
        vector<vector<int>> copList(51);
        for (int a = 1; a <= 50; a++)
            for (int b = 1; b <= 50; b++)
                if (g(a, b) == 1)
                    copList[a].push_back(b);

        vector<int> ans(n, -1);
        vector<int> depth(n, 0);
        vector<vector<int>> stk(51); // stk[v] = nodes with value v on current root path

        struct Ev { int node, parent; bool enter; };
        vector<Ev> st;
        st.reserve(2 * n);
        st.push_back({0, -1, true});

        while (!st.empty()) {
            Ev ev = st.back();
            st.pop_back();
            int u = ev.node, p = ev.parent;
            if (ev.enter) {
                int v = nums[u];
                depth[u] = (p == -1) ? 0 : depth[p] + 1;
                int best = -1, bestD = -1;
                for (int w : copList[v]) {
                    if (stk[w].empty()) continue;
                    int cand = stk[w].back();
                    if (depth[cand] > bestD) {
                        bestD = depth[cand];
                        best = cand;
                    }
                }
                ans[u] = best;
                stk[v].push_back(u);
                st.push_back({u, p, false}); // exit event
                for (int nxt : adj[u])
                    if (nxt != p) st.push_back({nxt, u, true});
            } else {
                stk[nums[u]].pop_back();
            }
        }

        return ans;
    }
};
```

