        vector<Ev> st;
        st.reserve(2 * n);
        st.push_back({0, -1, true});

        while (!st.empty()) {
            Ev ev = st.back();
            st.pop_back();
            int u = ev.node, p = ev.parent;
            if (ev.enter) {
                int v = nums[u];
                depth[u] = (p == -1) ? 0 : depth[p] + 1;
