class Solution {
public:
    bool isMatch(string s, string p) {
        // Collapse consecutive '*' characters (they are equivalent to a single '*')
        string q;
        q.reserve(p.size());
        for (char c : p) {
            if (c == '*' && !q.empty() && q.back() == '*') continue;
            q.push_back(c);
        }

        int m = s.size(), n = q.size();

        // dp[j] = whether s[0..i) matches q[0..j) for the current row i
        vector<char> dp(n + 1, 0);
        dp[0] = 1; // empty pattern matches empty string prefix

        // Row i = 0: empty string matches only a prefix of all '*'
        for (int j = 1; j <= n; ++j)
            dp[j] = dp[j - 1] && (q[j - 1] == '*');

        for (int i = 1; i <= m; ++i) {
            char prevDiag = dp[0]; // dp[i-1][0]
            dp[0] = 0;             // non-empty string never matches empty pattern
